 "content": "from collections import Counter, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            comps.append((color, cells))
    return comps


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, background)
    markers = []
    for idx, (color, cells) in enumerate(comps):
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r0 == r1 or c0 == c1:
            continue
        s = set(cells)
        # The marker is an L made of two complete adjoining bbox sides.
        for er in (r0, r1):
            for ec in (c0, c1):
                horiz = {(er, c) for c in range(c0, c1 + 1)}
                vert = {(r, ec) for r in range(r0, r1 + 1)}
                if s == horiz | vert:
                    dr = 1 if er == r0 else -1
                    dc = 1 if ec == c0 else -1
                    markers.append((idx, color, (er, ec), dr, dc))
    if not markers:
        return out
    # The L's open corner points to the opposite diagonal quadrant.
    idx, marker_color, (er, ec), dr, dc = max(markers, key=lambda m: len(comps[m[0]][1]))
    candidates = []
    for j, (color, cells) in enumerate(comps):
        if j == idx:
            continue
        # Component center must lie beyond the elbow, opposite both L arms.
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr - er) * dr < 0 and (cc - ec) * dc < 0:
            distance = min(abs(r-er) + abs(c-ec) for r, c in cells)
            candidates.append((distance, j, color))
    if candidates:
        _, target_idx, _ = min(candidates)
        target_color, cells = comps[target_idx]
        for r, c in cells:
            out[r][c] = marker_color
    return out
